"""Intent tests for risk.summary_stats (PL-03 step 2, RISK-04, TC-07)."""

from __future__ import annotations

import math

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={k: tuple(v) for k, v in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={k: tuple(v) for k, v in data["values"].items()},
    )


def _truncate(data: dict, n: int) -> dict:
    returns = data["returns"]
    return {
        "returns": {
            "base_date": returns["base_date"],
            "dates": returns["dates"][:n],
            "tickers": returns["tickers"],
            "values": {k: v[:n] for k, v in returns["values"].items()},
        },
        "window": data["window"],
        "annualized": data["annualized"],
        "values": {k: v[:n] for k, v in data["values"].items()},
    }


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_order(golden):
    data, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(data["vol"]))
    assert isinstance(result, tuple)
    assert all(isinstance(s, TickerSummary) for s in result)
    assert [s.ticker for s in result] == [e["ticker"] for e in expected["summary"]]


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_fields_match(golden, field):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    result = {s.ticker: s for s in summary_stats(_vol(data["vol"]))}
    for row in expected["summary"]:
        assert getattr(result[row["ticker"]], field) == pytest.approx(row[field], abs=tol)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    flat = next(row for row in expected["summary"] if row["ann_vol"] == 0)
    result = {s.ticker: s for s in summary_stats(_vol(data["vol"]))}
    summary = result[flat["ticker"]]
    assert summary.ann_vol == pytest.approx(0.0, abs=tol)
    assert summary.sharpe == pytest.approx(flat["sharpe"], abs=tol)
    assert math.isfinite(summary.sharpe)


@pytest.mark.intent
def test_tc07_last_rolling_vol_reported(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    result = {s.ticker: s for s in summary_stats(_vol(data["vol"]))}
    for row in expected["summary"]:
        assert result[row["ticker"]].last_vol == pytest.approx(row["last_vol"], abs=tol)


@pytest.mark.intent
def test_tc07_sharpe_is_return_over_vol(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    for s in summary_stats(_vol(data["vol"])):
        if s.ann_vol > 0:
            assert s.sharpe == pytest.approx(s.ann_return / s.ann_vol, abs=tol)


@pytest.mark.intent
def test_periods_per_year_scales_annualization(golden):
    data, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    result = {s.ticker: s for s in summary_stats(_vol(data["vol"]), periods_per_year=12)}
    for row in expected["summary"]:
        summary = result[row["ticker"]]
        assert summary.ann_return == pytest.approx(row["ann_return"] * 12 / 252, abs=tol)
        assert summary.ann_vol == pytest.approx(row["ann_vol"] * math.sqrt(12 / 252), abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("n", [0, 1])
def test_fewer_than_two_returns_raises(golden, n):
    data, _ = golden("risk", "TC-07")
    vol = _vol(_truncate(data["vol"], n))
    with pytest.raises(ValueError, match="(?i)two|2|return"):
        summary_stats(vol)

